<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api, label, role, time, uploadWithProgress } from './api';
import { uploadAccept, uploadProblem } from './upload-formats';
import AgentQuestionCard from './AgentQuestionCard.vue';
import AutoReviewPlan from './AutoReviewPlan.vue';
import { batchLabels, batchState, isBatchActive } from './auto-review-state.mjs';

const route = useRoute(), router = useRouter();
const batches = ref([]), selected = ref(null), files = ref([]), showUpload = ref(false), busy = ref(false), error = ref(''), progress = ref(0);
const limits = ref({ maxFiles: 20, maxFileBytes: 50 * 1024 ** 2, maxTotalBytes: 200 * 1024 ** 2 });
const resumePurpose = ref(''), backgroundChanged = ref(false);
const answerContent = ref('');
const ourEntity = ref('');
const stageText = s => batchLabels[s] || s || '—';
const riskCount = b => b.review?.status === 'completed' && b.findings ? b.findings.filter(f => f.check_status === 'fail').length : b.result?.findingCount ?? '—';
const roleText = value => ({ main: '主合同', supplement: '补充协议', schedule: '清单附件', reference: '参考材料', uncertain: '待核实' }[value] || '待核实');
const active = isBatchActive;
const now = ref(Date.now());
const state = computed(() => batchState(selected.value, now.value));
const skills = computed(() => (selected.value?.activity || []).filter(e=>e.type==='skill_loaded'));
const toolEvents = computed(() => (selected.value?.activity || []).filter(e=>e.type==='tool').slice(-40).reverse());
const currentArtifacts = computed(() => (selected.value?.artifacts || []).filter(a=>a.review_id===selected.value?.main_review_id));
const reviewableArtifacts = computed(() => currentArtifacts.value.filter(a => ['annotated_comments', 'tracked_revisions'].includes(a.kind) && a.status === 'ready' && a.version_id));
const artifactLink = artifact => `/auto-review/${selected.value.id}/artifacts/${artifact.id}`;
const artifactDocument = artifact => selected.value?.documents?.find(doc => doc.id === artifact.batch_document_id);
const artifactReady = artifact => artifact.status === 'ready' && !!artifact.version_id;
function artifactTitle(artifact) {
  return artifact.kind === 'report' || artifactReady(artifact) ? artifact.filename : artifactDocument(artifact)?.filename || 'Word 建议稿未生成';
}
function artifactSummary(artifact) {
  if (artifact.kind === 'report') return '审查报告';
  if (artifactReady(artifact)) return artifact.kind === 'annotated_comments' ? `已定位 ${artifact.locatedFindingIds.length} 条批注，位置待核实 ${artifact.unlocatedFindingIds.length} 条；正文未自动替换` : `历史修订稿 · 已自动修改 ${artifact.locatedFindingIds.length} 项，待核实 ${artifact.unlocatedFindingIds.length} 项`;
  if (artifactDocument(artifact)?.ingest_status === 'failed') return '原件读取失败，未纳入本次内容审查';
  return '未生成 Word 建议稿；相关审查意见请查看审查报告';
}
const groups = computed(() => ['high','medium','low','uncertain'].map(severity => ({ severity, findings: (selected.value?.findings || []).filter(f=> f.check_status !== 'pass' && (f.check_status === 'uncertain' ? severity === 'uncertain' : f.severity === severity)) })));
const completed = computed(() => batches.value.filter(b => b.status === 'completed').length);
let timer, clockTimer, closed = false, detailRequest = 0, polling = false, clientKey = '', signature = '';
async function loadList(quiet = false) { const value = await api('/auto-review-batches', { quiet }); if (closed) return; batches.value = value; if (route.params.id) await loadDetail(route.params.id, quiet); }
async function loadDetail(id, quiet = false) { const n = ++detailRequest; try { const value = await api(`/auto-review-batches/${id}`, { quiet }); if (!closed && n === detailRequest && route.params.id === id) selected.value = value; } catch (e) { if (!quiet) error.value = e.message; } }
function pickFiles(picked) {
  const next = [...files.value,...picked].filter((f,i,list)=>list.findIndex(x=>x.name===f.name&&x.size===f.size&&x.lastModified===f.lastModified)===i);
  const problem = uploadProblem(next) || (next.length > limits.value.maxFiles ? `每批最多 ${limits.value.maxFiles} 份材料` : '') || (next.some(f=>f.size>limits.value.maxFileBytes) ? '超过单文件大小限制' : '') || (next.reduce((n,f)=>n+f.size,0)>limits.value.maxTotalBytes ? '超过批次总大小限制' : '');
  if (problem) { error.value=problem; return; } files.value=next; error.value='';
}
function selectFiles(e) { pickFiles([...e.target.files]); e.target.value=''; }
async function submit() {
  if (!files.value.length || busy.value) return;
  busy.value = true; error.value = ''; progress.value = 0;
  try {
    const nextSignature=JSON.stringify([ourEntity.value,files.value.map(f=>[f.name,f.size,f.lastModified])]); if(nextSignature!==signature){clientKey=crypto.randomUUID();signature=nextSignature;}
    const data = new FormData(); files.value.forEach(file => data.append('files[]', file)); data.set('background', JSON.stringify({ ourEntity: ourEntity.value })); data.set('clientKey', clientKey);
    const batch = await uploadWithProgress('/auto-review-batches', data, value=>progress.value=value);
    showUpload.value = false; files.value = []; ourEntity.value = ''; signature='';clientKey=''; await router.push(`/auto-review/${batch.id}`); await loadList(true);
  } catch (e) { error.value = e.message; } finally { busy.value = false; }
}
async function control(action, answer = {}) { if (!selected.value || busy.value) return; busy.value=true;error.value=''; try { const body=action==='cancel'?{}:{...answer,...(backgroundChanged.value?{background:{...selected.value.background,purpose:resumePurpose.value}}:{})}; await api(`/auto-review-batches/${selected.value.id}/${action}`,{method:'POST',body,quiet:true});backgroundChanged.value=false;answerContent.value='';await loadList(true); }catch(e){error.value=e.message;}finally{busy.value=false;} }
function answerQuestion(answer) { return control('resume', answer); }
function jumpTo(id) { document.getElementById(id)?.scrollIntoView({ block: 'start' }); }
function evidenceLink(e) {const doc=selected.value?.documents.find(d=>d.version_id===e.versionId);return doc?`/contracts/${doc.contract_id}?version=${doc.version_id}&block=${encodeURIComponent(e.blockId)}`:'/auto-review';}
watch(() => route.params.id, id => { detailRequest++;selected.value=null;error.value='';backgroundChanged.value=false;answerContent.value='';if(id)loadDetail(id); });
watch(() => selected.value?.main_review_id, () => { answerContent.value=''; });
onMounted(async () => { clockTimer=setInterval(()=>{now.value=Date.now();},1000);try{limits.value=await api('/auto-review-limits');await loadList();}catch(e){error.value=e.message;} timer=setInterval(async()=>{if(polling||closed||busy.value)return;polling=true;try{await loadList(true);}catch{}finally{polling=false;}},3500); });
onUnmounted(() => {closed=true;detailRequest++;clearInterval(timer);clearInterval(clockTimer);});
</script>

<template>
  <section class="page-heading auto-heading">
    <div><div class="eyebrow">合同审查工作台</div><h1>自动评审</h1><p>上传合同及补充材料，自动审查并生成报告和带修订的 Word 文件。</p></div>
    <div class="action-row"><button v-if="selected && active(selected.status)" @click="control('cancel')" :disabled="busy">停止批次</button><button v-if="role('business','legal')" class="primary" @click="showUpload=true">＋ 新建自动评审</button></div>
  </section>
  <p v-if="error" class="notice danger" role="alert">{{ error }}</p>
  <p v-if="route.params.id && !selected && !error" role="status">正在加载批次…</p>
  <div v-if="selected" class="auto-detail">
    <button class="text-btn auto-back" @click="router.push('/auto-review')">← 返回批次列表</button>
    <div class="panel auto-detail-head"><div><span class="badge" :class="selected.status">{{ state.question ? '等待你回答' : selected.status === 'needs_attention' ? '执行暂停' : state.label }}</span><h2>{{ selected.result?.title || '自动评审批次' }}</h2><p class="muted">{{ selected.source === 'dingtalk' ? '钉钉审批收件' : '手动多文件上传' }} · {{ selected.documents?.length || 0 }} 份材料 · 提交于 {{ time(selected.created_at) }}</p><p class="auto-entity">我方主体：{{ selected.background?.ourEntity || '由合同识别，无法确认的事项列为待核实' }}</p></div><button class="text-btn auto-refresh" :disabled="busy" @click="loadDetail(selected.id)">↻ 刷新</button></div>
    <section class="panel auto-status" :class="state.tone" aria-labelledby="batch-status-title">
      <div class="auto-status-top"><div><p class="auto-kicker">{{ state.running ? '当前进度' : '当前状态与下一步' }}</p><h2 id="batch-status-title">{{ state.title }}</h2><p class="auto-status-description" role="status">{{ state.description }}</p><p class="auto-status-note" v-if="state.canResume && !state.question && !state.reportReady">当前没有需要你回答的问题，直接继续即可。无需重新上传合同。</p><p class="auto-model-wait auto-status-note" v-if="state.modelWait">当前阶段：{{ state.label }}<template v-if="state.modelWait.number != null"> · 第 {{ state.modelWait.number }} 次模型请求</template><template v-if="state.modelWait.elapsed != null"> · 本次已用时 {{ state.modelWait.elapsed }} 秒</template><template v-if="state.modelWait.progressPolicy"><template v-if="state.modelWait.idleTimeout != null"> · 开始输出后，连续 {{ state.modelWait.idleTimeout }} 秒无新内容才暂停</template><template v-if="state.modelWait.timeout != null"> · 单次最长 {{ state.modelWait.timeout }} 秒</template></template><template v-else-if="state.modelWait.timeout != null">（单次时限 {{ state.modelWait.timeout }} 秒）</template></p><p class="auto-status-note" v-if="state.running">执行进度会自动更新。最近活动：{{ time(state.lastActivity?.created_at || selected.updated_at) }}</p></div>
        <div class="auto-main-actions"><router-link v-if="reviewableArtifacts.length" class="primary auto-open-review" :to="artifactLink(reviewableArtifacts[0])">打开合同审阅 →</router-link><button v-if="state.downloadable" class="primary" @click="jumpTo('auto-artifacts')">查看并下载文件 <span>↓</span></button><button v-else-if="state.question" class="primary" @click="jumpTo('auto-next-action')">回答问题并继续 <span>↓</span></button><button v-else-if="state.canResume && role('business','legal')" class="primary" :disabled="busy" @click="control('resume')">{{ busy ? '正在恢复…' : backgroundChanged ? '按补充信息重新审查' : state.action }}</button><span v-if="state.running" class="auto-running"><i aria-hidden="true"></i> 正在处理</span><button v-if="state.reportReady" class="text-btn" @click="jumpTo('auto-report')">查看审查意见 →</button></div>
      </div>
      <section v-if="state.pauseDetails" class="auto-pause-details" aria-labelledby="pause-reason-title">
        <h3 id="pause-reason-title">为什么暂停：{{ state.pauseDetails.reason }}</h3>
        <p class="auto-pause-trigger">{{ state.pauseDetails.trigger }}</p>
        <dl class="auto-pause-facts"><div><dt>暂停阶段</dt><dd>{{ state.pauseDetails.stage }}</dd></div><div><dt>最近完成的操作</dt><dd>{{ state.pauseDetails.lastOperation }}</dd></div><div><dt>已保存的进度</dt><dd>{{ state.pauseDetails.savedWork }}</dd></div></dl>
        <p v-if="state.pauseDetails.recordNote" class="auto-pause-record-note">{{ state.pauseDetails.recordNote }}</p>
        <ol v-if="state.pauseDetails.attempts.length" class="auto-pause-attempts" aria-label="失败请求记录"><li v-for="(attempt,index) in state.pauseDetails.attempts" :key="index"><div><b>失败请求 {{ index + 1 }} · {{ attempt.result }}</b><span>耗时 {{ attempt.duration }}</span></div><p>{{ attempt.detail }}<span v-if="attempt.at"> · {{ time(attempt.at) }}</span><span> · {{ attempt.source }}</span></p></li></ol>
        <p v-if="state.pauseDetails.unknown" class="auto-pause-unknown">{{ state.pauseDetails.unknown }}</p>
        <p class="auto-pause-next">{{ state.pauseDetails.nextAction }}</p>
        <details class="auto-pause-code"><summary>查看诊断编号</summary><code>{{ state.pauseDetails.code }}</code></details>
      </section>
      <ol class="auto-stepper" aria-label="审查流程"><li v-for="(phase,index) in state.phases" :key="phase.title" :class="{done:phase.done,current:phase.current && state.running,paused:phase.current && phase.status==='已暂停'}" :aria-current="phase.current ? 'step' : undefined"><span class="auto-step-number" aria-hidden="true">{{ phase.done ? '✓' : index + 1 }}</span><div><b>{{ phase.title }}</b><small>{{ phase.detail }}</small></div><span class="auto-step-tag">{{ phase.status }}</span></li></ol>
      <p v-if="state.pauseDetails" class="auto-step-explanation">橙色标记暂停的位置，表示该步骤尚未完成。已完成的步骤保留勾选，后续步骤显示“待进行”。</p>
    </section>
    <section v-if="state.canResume" id="auto-next-action" class="panel padded auto-next-action" aria-labelledby="next-action-title">
      <template v-if="state.question"><h2 id="next-action-title">请在这里回答</h2><p class="auto-question-intro">{{ state.question.content }}</p><AgentQuestionCard v-if="state.question.data?.questions?.length" :key="state.question.id" :question="state.question" :busy="busy" @answer="answerQuestion" /><form v-else class="auto-answer-form" @submit.prevent="answerQuestion({questionId:state.question.id,content:answerContent})"><label for="batch-answer">你的回答<span class="required-hint">（必填）</span></label><textarea id="batch-answer" v-model="answerContent" :disabled="busy" rows="4" maxlength="20000" placeholder="针对上方问题填写已知事实；无法确认的内容请写“暂不清楚”。" required></textarea><p class="field-help">回答会提交到当前审查会话，提交后自动继续。</p><button class="primary" :disabled="busy || !answerContent.trim()">{{ busy ? '正在提交…' : '提交回答并继续审查' }}</button></form></template>
      <template v-else><h2 id="next-action-title">{{ state.reportReady ? '处理剩余事项' : '继续本次审查' }}</h2><p>{{ state.reportReady ? '先查看已生成的报告和文件，再决定是否重试未完成项。' : '直接点击上方继续按钮，系统将沿用原材料和已保存的审查会话。' }}</p><button v-if="state.reportReady && role('business','legal')" :disabled="busy" @click="control('resume')">{{ busy ? '正在处理…' : state.action }}</button><details class="auto-background"><summary>有新的合同外事实？在这里补充（可选）</summary><p class="field-help">例如实际付款情况、双方已确认的交付安排。保存后将结合新事实重新全面审查；技术中断无需填写。</p><label for="batch-background">补充背景信息</label><textarea id="batch-background" :value="backgroundChanged ? resumePurpose : selected.background?.purpose || ''" :disabled="busy" rows="3" maxlength="3000" placeholder="填写新事实及其来源；不要填写尚未确认的假设。" @input="resumePurpose=$event.target.value; backgroundChanged=true"></textarea><button class="primary" :disabled="busy || !backgroundChanged" @click="control('resume')">{{ busy ? '正在提交…' : '提交补充信息并重新审查' }}</button></details></template>
      <p v-if="error" class="error-text" role="alert">{{ error }}</p>
    </section>
    <div class="auto-columns">
      <section class="panel"><div class="panel-heading"><h2>材料与角色</h2></div><div class="auto-docs"><article v-for="doc in selected.documents" :key="doc.id"><div><b>{{ doc.filename }}</b><small>{{ roleText(doc.role) }}</small><p v-if="doc.error_message" class="error-text">{{ doc.error_message }}</p><div class="action-row auto-source-actions"><router-link v-if="doc.contract_id && doc.version_id" :to="`/contracts/${doc.contract_id}?version=${doc.version_id}`">查看原文</router-link><a v-if="doc.version_id" :href="`/api/files/${doc.version_id}?download=1`">下载原件</a></div></div><span class="badge" :class="doc.ingest_status">{{ doc.ingest_status === 'ready' ? '可读取' : '读取失败' }}</span></article></div><p class="notice subtle">角色由 Agent 判断；不确定事项不阻塞可完成的审查。</p></section>
      <section class="panel auto-overview"><div class="panel-heading"><h2>本次审查概况</h2></div><dl><div><dt>全文读取</dt><dd>{{ state.total ? `${state.read} / ${state.total} 段` : '等待解析' }}</dd></div><div><dt>审查计划</dt><dd>{{ state.planDescription }}</dd></div><div><dt>审查报告</dt><dd>{{ state.reportReady ? '已生成' : selected.review?.candidateSaved ? '候选已保存，待复核' : '尚未生成' }}</dd></div><div><dt>可下载文件</dt><dd>{{ state.downloadable }} 份</dd></div></dl><p class="field-help">全文读取表示材料已读，不代表已完成风险判断。</p></section>
    </div>
    <AutoReviewPlan :batch="selected" />
    <section v-if="role('legal')" class="panel padded auto-learning"><h2>本次法务经验整理</h2><p class="field-help">在程序中审阅并保存后，结合正文修改、修订处理、批注回复及修改理由尝试提炼技能草稿。未处理的 AI 内容和批注已处理状态不视为认可；新技能审核通过后才复用。</p><p v-if="!selected.learningSources?.length" class="muted">尚无已保存的人工审阅记录。</p><article v-for="item in selected.learningSources || []" :key="item.id"><div><b>{{ item.contract_title }}</b><p>{{ item.resultText }}</p><small>{{ time(item.created_at) }}</small></div><router-link :to="`/experience?source=${item.id}`">{{ item.status==='failed' ? '查看原因并重试' : item.pendingKnowledgeCount ? '查看并审核草稿' : '查看整理记录' }} →</router-link></article></section>
    <section v-if="state.reportReady" id="auto-report" class="panel auto-report"><div class="panel-heading"><h2>审查结果</h2><span class="muted">风险 {{ riskCount(selected) }} 条</span></div><p>{{ selected.review.agentResult?.summary }}</p><template v-for="group in groups" :key="group.severity"><template v-if="group.findings.length"><h3 class="padded">{{ group.severity==='uncertain' ? '待核实事项' : label(group.severity) }} · {{ group.findings.length }}</h3><div class="risk-grid"><article v-for="finding in group.findings" :key="finding.id" :class="['risk-card',finding.severity]"><h3>{{ finding.title }}</h3><p>{{ finding.reason }}</p><details><summary>修改建议与原文</summary><p>{{ finding.suggestion }}</p><p v-for="(e,index) in finding.evidence" :key="index"><router-link :to="evidenceLink(e)">{{ selected.documents.find(d=>d.version_id===e.versionId)?.filename }} / {{ e.blockId }} →</router-link><br>{{ e.quote }}</p></details></article></div></template></template><details class="padded" v-if="selected.review.agentResult?.crossDocumentReview"><summary>跨文件核对</summary><p v-for="row in selected.review.agentResult.crossDocumentReview" :key="row.category"><b>{{ {amendments:'补充条款',amounts_terms:'金额与期限',precedence:'适用顺序'}[row.category] }}</b>：{{ row.reason }}</p></details><ul class="limitations"><li v-for="(item,index) in selected.review.agentResult?.limitations || []" :key="index">{{ item }}</li></ul></section>
    <section v-if="currentArtifacts.length" id="auto-artifacts" class="panel"><div class="panel-heading"><h2>报告与批注</h2><span class="muted">{{ state.downloadable }} 份产物可下载（不含原件）</span></div><p class="padded">AI 默认只提供批注，原文由法务调整。点击“查看批注”可在程序中处理意见并保存人工修改；历史修订稿仍可审阅。无法生成批注版的材料可查看审查报告及原件。</p><div class="artifact-list"><article v-for="artifact in currentArtifacts" :key="artifact.id"><div><b>{{ artifactTitle(artifact) }}</b><small>{{ artifactSummary(artifact) }}</small><p v-if="artifact.error_message" class="error-text">{{ artifact.error_message }}</p><details v-if="artifact.details?.unresolved?.length"><summary>{{ artifact.kind === 'annotated_comments' ? '批注位置待核实' : '未自动改写的意见' }}</summary><p v-for="(item,index) in artifact.details.unresolved" :key="index">{{ item.title }}：{{ item.reason }}</p></details></div><div class="action-row auto-artifact-actions"><router-link v-if="['annotated_comments','tracked_revisions'].includes(artifact.kind) && artifactReady(artifact)" class="primary auto-open-review" :to="artifactLink(artifact)">{{ artifact.kind === 'annotated_comments' ? '查看批注' : '在程序中审阅' }}</router-link><a v-if="artifact.downloadUrl" class="auto-download" :href="artifact.downloadUrl">{{ artifact.kind==='report' ? '下载报告' : artifact.kind==='annotated_comments' ? '下载批注版' : '下载带修订 DOCX' }}</a><template v-if="artifactDocument(artifact)"><router-link v-if="artifactDocument(artifact).contract_id && artifactDocument(artifact).version_id" class="auto-download" :to="`/contracts/${artifactDocument(artifact).contract_id}?version=${artifactDocument(artifact).version_id}`">查看原文</router-link><a v-if="artifactDocument(artifact).version_id" class="auto-download" :href="`/api/files/${artifactDocument(artifact).version_id}?download=1`">下载原件</a></template></div></article></div></section>
    <details v-if="selected.artifacts?.length > currentArtifacts.length" class="panel padded"><summary>历史产物</summary><p v-for="a in selected.artifacts.filter(a=>a.review_id!==selected.main_review_id)" :key="a.id"><a v-if="a.downloadUrl" :href="a.downloadUrl">{{ a.filename }} · {{ time(a.created_at) }}</a></p></details>
    <details class="panel padded auto-execution-log"><summary>查看执行记录与诊断信息</summary><p class="muted">批次编号：<span class="mono">{{ selected.id }}</span><template v-if="selected.review?.errorCode"> · 原因代码：{{ selected.review.errorCode }}</template></p><section v-if="selected.executionPlan?.documents?.length" class="auto-role-evidence"><h3>材料角色判断依据</h3><p v-for="doc in selected.executionPlan.documents" :key="doc.versionId"><b>{{ selected.documents.find(d=>d.version_id===doc.versionId)?.filename || '历史材料' }}</b>：{{ doc.reason }}</p></section><details v-if="skills.length" class="auto-technical-skills"><summary>方法原始标识（供排查使用）</summary><p v-for="skill in skills" :key="skill.id"><code>{{ skill.data.name }}</code></p></details><details v-if="toolEvents.length" class="auto-tool-results"><summary>工具调用与结果</summary><p v-for="event in toolEvents" :key="event.id"><code>{{ event.data.name }}</code> · {{ event.data.ok ? '已完成' : '待纠正' }} · {{ event.data.message }}</p></details><div class="auto-timeline"><article v-for="event in (selected.events || []).slice().reverse()" :key="event.id"><i></i><div><b>{{ event.type === 'needs_attention' ? state.description : event.data?.message || stageText(event.stage) }}</b><small>{{ time(event.created_at) }}</small></div></article></div><p v-for="event in (selected.activity || []).filter(e=>e.type==='model_failed')" :key="event.id" class="error-text">{{ time(event.created_at) }} · {{ event.data.message }}</p></details>
  </div>
  <template v-else-if="!route.params.id">
    <div class="stat-grid auto-stats"><div class="stat-card"><span>全部批次</span><strong>{{ batches.length.toString().padStart(2,'0') }}</strong></div><div class="stat-card"><span>已完成</span><strong>{{ completed.toString().padStart(2,'0') }}</strong></div><div class="stat-card"><span>处理中</span><strong>{{ batches.filter(b => active(b.status)).length.toString().padStart(2,'0') }}</strong></div><div class="stat-card"><span>需要处理</span><strong>{{ batches.filter(b => ['partial','needs_attention','failed'].includes(b.status)).length.toString().padStart(2,'0') }}</strong></div></div>
    <section class="panel"><div class="panel-heading"><h2>审查批次 <span class="count">{{ batches.length }}</span></h2><button class="text-btn" @click="loadList()">↻ 刷新</button></div><div class="table-scroll"><table><thead><tr><th>批次</th><th>来源</th><th>材料</th><th>阶段</th><th>风险</th><th>建议稿</th><th>更新时间</th><th></th></tr></thead><tbody><tr v-for="batch in batches" :key="batch.id" class="clickable" @click="router.push(`/auto-review/${batch.id}`)"><td><router-link :to="`/auto-review/${batch.id}`"><strong class="contract-title">{{ batch.result?.title || '自动评审批次' }}</strong></router-link><small class="mono">{{ batch.id.slice(0, 8) }}</small></td><td>{{ batch.source === 'dingtalk' ? '钉钉审批' : '手动上传' }}</td><td>{{ batch.documents?.length || 0 }} 份</td><td><span class="badge" :class="batch.status">{{ stageText(batch.stage || batch.status) }}</span></td><td>{{ riskCount(batch) }}</td><td>{{ batch.artifactCount }} 份</td><td class="muted nowrap">{{ time(batch.updated_at) }}</td><td class="arrow">↗</td></tr></tbody></table><div v-if="!batches.length" class="empty-state"><span class="empty-icon">◌</span><h3>还没有自动评审批次</h3><p>上传主合同和补充材料后，Agent 会自动完成审查并生成 Word 批注建议稿，原文由法务调整。</p><button v-if="role('business','legal')" class="primary" @click="showUpload=true">新建第一批</button></div></div></section>
  </template>
  <el-dialog v-model="showUpload" title="新建自动评审" :close-on-click-modal="!busy" :close-on-press-escape="!busy" :show-close="!busy" width="min(640px, calc(100vw - 32px))">
    <form class="stack" @submit.prevent="submit">
      <p>每批最多 {{ limits.maxFiles }} 份，单文件 {{ limits.maxFileBytes/1024**2 }}MB，总计 {{ limits.maxTotalBytes/1024**2 }}MB。上传后自动全面审查，无需逐条确认。</p>
      <label class="drop-zone" @dragover.prevent @drop.prevent="!busy && pickFiles([...$event.dataTransfer.files])">拖拽材料到这里，或点击选择<input type="file" multiple :accept="uploadAccept" :disabled="busy" @change="selectFiles" /><span>已选择 {{ files.length }} 份 · {{ (files.reduce((n,f)=>n+f.size,0)/1024**2).toFixed(1) }}MB</span></label>
      <ul class="picked-files"><li v-for="(file,index) in files" :key="index">{{ file.name }} <button type="button" :disabled="busy" @click="files.splice(index,1)">移除</button></li></ul>
      <label>我方主体（可选）<input v-model="ourEntity" :disabled="busy" maxlength="200" placeholder="填写公司全称，Agent 将根据合同识别交易角色" /></label>
      <p class="field-help">批次名称自动生成。Agent 根据我方主体和合同判断交易立场，审查全部材料及适用风险；无法确认的信息列为待核实。</p>
      <p v-if="error" class="error-text" role="alert">{{ error }}</p>
      <progress v-if="busy" :value="progress" max="100" aria-label="上传进度"></progress>
      <div class="dialog-actions"><span class="muted">{{ busy ? progress===100 ? '材料已上传，正在保存批次…' : `上传中 ${progress}%` : '原件和历次产物始终保留' }}</span><button class="primary" :disabled="busy || !files.length">{{ busy ? '正在提交…' : '上传并自动评审' }}</button></div>
    </form>
  </el-dialog>
</template>

